:root {
  --bg: #f6f7f5;
  --card: #ffffff;
  --text: #1d2320;
  --muted: #66706a;
  --border: #d9ded9;
  --accent: #1f7a4d;
  --accent-text: #ffffff;
  --error: #b42318;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--text);
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #121513;
    --card: #1b1f1c;
    --text: #e7ebe8;
    --muted: #9aa49e;
    --border: #2e3530;
    --accent: #3fb37a;
    --accent-text: #0c120e;
    --error: #ff8a80;
  }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); }
.page { max-width: 760px; margin: 0 auto; padding: 24px 16px 48px; }
.topbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.topbar h1 { margin: 0; font-size: 1.6rem; }
.who { display: flex; align-items: center; gap: 10px; color: var(--muted); }
.card { background: var(--card); border: 1px solid var(--border); border-radius: 12px; padding: 20px; margin: 20px 0; }
.card h2 { margin-top: 0; font-size: 1.2rem; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 0 16px; }
.field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 14px; }
.field span { font-weight: 600; font-size: 0.9rem; }
.field small { color: var(--muted); }
input, select, textarea {
  font: inherit; color: var(--text); background: var(--bg);
  border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px;
}
button {
  font: inherit; font-weight: 600; cursor: pointer; border-radius: 8px; padding: 8px 16px;
  border: 1px solid var(--accent); background: var(--accent); color: var(--accent-text);
}
button.secondary { background: transparent; color: var(--accent); }
button:disabled { opacity: 0.6; cursor: default; }
.actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.muted { color: var(--muted); font-size: 0.85rem; }
.ok { color: var(--accent); }
.error, .field small.error { color: var(--error); }

